package com.jobpilot.auth;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/auth") public class AuthController{private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/register")AuthDtos.AuthResponse register(@Valid @RequestBody AuthDtos.RegisterRequest r){return service.register(r);}@PostMapping("/login")AuthDtos.AuthResponse login(@Valid @RequestBody AuthDtos.LoginRequest r){return service.login(r);}}
